interface StatProps {
  number: string;
  label: string;
}

function Stat({ number, label }: StatProps) {
  return (
    <div className="text-center">
      <p className="text-2xl font-bold text-white mx-5">{number}</p>
      <p className="text-sm text-gray-400 mt-1 mx-5 whitespace-nowrap">{label}</p>
    </div>
  );
}

interface ProblemCardProps {
  icon: React.ReactNode;
  title: string;
  description: string;
}

function ProblemCard({ icon, title, description }: ProblemCardProps) {
  return (
    <div className="bg-white dark:bg-navy-800 border border-gray-100 dark:border-white/10 rounded-2xl p-6 hover:shadow-md transition-all duration-200 group">
      <div className="w-11 h-11 bg-navy-700 text-white rounded-xl flex items-center justify-center mb-5 group-hover:scale-110 transition-transform">
        {icon}
      </div>
      <h3 className="font-semibold text-navy-700 dark:text-white text-lg mb-2">{title}</h3>
      <p className="text-gray-600 dark:text-gray-400 text-sm leading-relaxed">{description}</p>
    </div>
  );
}

interface SolutionCardProps {
  icon: React.ReactNode;
  title: string,
  description: string;
}

function SolutionCard({ icon, title, description }: SolutionCardProps) {
  return (
    <div className="bg-white dark:bg-navy-800 border border-gray-100 dark:border-white/10 rounded-2xl p-6 hover:shadow-md transition-all duration-200 group">
      <div className="w-11 h-11 bg-navy-700 text-white rounded-xl flex items-center justify-center mb-5 group-hover:scale-110 transition-transform">
        {icon}
      </div>
      <h3 className="font-semibold text-navy-700 dark:text-white mb-2">{title}</h3>
      <p className="text-sm text-gray-600 dark:text-gray-400 leading-relaxed">{description}</p>
    </div>
  );
}

interface StepProps {
  number: number;
  title: string;
  description: string;
}

function Step({ number, title, description }: StepProps) {
  return (
    <div className="flex-1 relative">
      <div className="flex items-center gap-4">
        <div className="w-10 h-10 rounded-full bg-navy-700 text-white flex items-center justify-center font-bold text-lg flex-shrink-0">
          {number}
        </div>
        <div>
          <h3 className="font-semibold text-navy-700 dark:text-white">{title}</h3>
          <p className="text-sm text-gray-600 dark:text-gray-400 mt-1">{description}</p>
        </div>
      </div>
    </div>
  )
}

interface BenefitListProps {
  title: string;
  items: string[];
}

function BenefitList({ title, items }: BenefitListProps) {
  return (
    <div className="bg-white dark:bg-navy-800 rounded-2xl p-8 border border-gray-100 dark:border-white/10">
      <h3 className="font-semibold text-navy-700 dark:text-white mb-6 flex items-center gap-2">
        {title}
      </h3>
      <ul className="space-y-4">
        {items.map((item, index) => (
          <Reveal key={index} delay={index * 80}>
            <li className="flex items-start gap-3 text-sm">
              <div className="mt-1 text-green-500">
                <IconPoint size={18} />
              </div>
              <span className="text-gray-700 dark:text-gray-300">{item}</span>
            </li>
          </Reveal>
        ))}
      </ul>
    </div>
  );
}
function Navbar() {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const navigate = useNavigate()
  return (
    <nav className="bg-white dark:bg-navy-800 border-b border-gray-100 dark:border-white/10 sticky top-0 z-50">
      <div className="max-w-full mx-auto px-6 py-5 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-full overflow-hidden bg-white flex items-center justify-center">
            <img
              src={logo}
              alt="UniTrade Logo"
              className="w-full h-full object-cover"
              onError={(e) => {
                e.currentTarget.src =
                  "https://placehold.co/120x40/0d1f4e/white?text=UniTrade";
              }}
            />
          </div>
          <h1 className="font-bold text-navy-700 dark:text-white text-3xl mb-2">UniTrade</h1>
        </div>


        <div className="hidden md:flex items-center gap-8 text-sm font-medium ml-auto mr-4">
          <a href="#problem" className="hover:text-navy-500 dark:hover:text-blue-400 transition-colors">The Problem</a>
          <a href="#solution" className="hover:text-navy-500 dark:hover:text-blue-400 transition-colors">The Solution</a>
          <a href="#how-it-works" className="hover:text-navy-500 dark:hover:text-blue-400 transition-colors">How it works</a>
          <a href="#for-buyerssellers" className="hover:text-navy-500 dark:hover:text-blue-400 transition-colors">For buyers</a>
          <a href="#for-buyerssellers" className="hover:text-navy-500 dark:hover:text-blue-400 transition-colors">The sellers</a>
        </div>

        <div className="flex items-center gap-4">
          <button
            onClick={() => navigate('/auth/Signup')}
            className="bg-navy-700 hover:bg-navy-600 text-white px-6 py-2.5 text-sm font-semibold rounded-full transition-colors">
            Get Started
          </button>

          <button
            className="md:hidden"
            data-testid="mobile-menu-toggle"
            aria-label="Toggle menu"
            aria-expanded={isMenuOpen}
            onClick={() => setIsMenuOpen(!isMenuOpen)}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6H16M4 12H16M4 18H16" />
            </svg>
          </button>
        </div>


      </div>

      {isMenuOpen && (
        <div data-testid="mobile-menu" className="md:hidden border-t bg-white dark:bg-navy-800 py-4 px-6 space-y-4 text-sm">
          <a href="#problem" className="block py-2" onClick={() => setIsMenuOpen(false)}>The Problem</a>
          <a href="#solution" className="block py-2" onClick={() => setIsMenuOpen(false)}>The Solution</a>
          <a href="#how-it-works" className="block py-2" onClick={() => setIsMenuOpen(false)}>How it works</a>
          <a href="#for-buyerssellers" className="block py-2" onClick={() => setIsMenuOpen(false)}>For buyers</a>
          <a href="#for-buyerssellers" className="block py-2" onClick={() => setIsMenuOpen(false)}>For sellers</a>
        </div>
      )}
    </nav>
  )
}

const ALEX_IMAGE = "data:image/png;base64,";
type AvatarStage = 'thinking' | 'answer' | 'joy';

interface AlexAvatarProps {
  className?: string;
  onClick?: () => void;
}

function AlexAvatar({ className = '', onClick }: AlexAvatarProps) {
  const [stage, setStage] = useState<AvatarStage>('thinking');
  const [cycleKey, setCycleKey] = useState(0);

  useEffect(() => {
    const timers: ReturnType<typeof setTimeout>[] = [];

    timers.push(setTimeout(() => setStage('answer'), 1800));
    timers.push(setTimeout(() => setStage('joy'), 3600));
    timers.push(setTimeout(() => setStage('thinking'), 6200));
    timers.push(
      setTimeout(() => {
        setCycleKey((k) => k + 1)
      }, 6200)
    );
    return () => timers.forEach(clearTimeout);
  }, [cycleKey]);

  const bubbleText = stage === 'thinking' ? 'AgileBridge + DevNexus' : 'UniTrade';
  const dots = stage === 'thinking' ? (
    <span className="inline-flex gap-1 ml-1">
      <span className="animate-bounce delay-0">.</span>
      <span className="animate-bounce delay-150">.</span>
      <span className="animate-bounce delay-300">.</span>
    </span>
  ) : null;

  const bubbleColor =
    stage === 'thinking'
      ? 'bg-navy-700'
      : stage === 'answer'
        ? 'bg-blue-400 shadon-lg shadow-green-500/30'
        : 'bg-blue-400'
  return (
    <div
      className={`relative flex flex-col items-center ${className}`}
      onClick={onClick}
      role="img"
      aria-label="Alex avatar"
    >
      <div className="relative mb-6 flex flex-col items-center">
        <div
          className={`px-6 py-4 rounded-[2rem] text-white text-sm font-medium
                        transition-all duration-500 max-w-[220px] text-center
                        ${bubbleColor}
                        ${stage === 'answer' ? 'scale-105' : 'scale-100'}`}>
          {bubbleText}
          {dots}
        </div>
        <div className={`w-4 h-4 rounded-full mt-1 transition-colors duration-500 ${bubbleColor}`} />
        <div className={`w-2.5 h-2.5 rounded-full mt-1 transition-colors duration-500 ${bubbleColor}`} />
      </div>
      <div
        key={cycleKey}
        className={
          `w-56 h-56 md:w-72 md:h-72 overflow-hidden
          transition-transform duration-500
          ${stage === 'thinking' ? 'animate-pulse-slow' : ''}
          ${stage === 'joy' ? 'animate-joy-bounce' : ''}`
        }
      >
        <img src={ALEX_IMAGE}
          alt="Alex Avatar"
          className="w-ful h-full object-contain"
        />
      </div>
      {stage === 'joy' && (
        <div className="absolute -top-6 -right-6 text-3xl animate-sparkle" />
      )}
      {stage === 'joy' && (
        <div className="absolute -top-2 -left-6 text-2xl animate-sparkle-delay" />
      )}
    </div>

  )
}
